pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 wrongValue) internal {
        wrongValue = bound(wrongValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        uint256 limit;
        try c.currentBetLimit() returns (uint256 __r) { limit = __r; } catch { return; }
        vm.assume(wrongValue != limit);
        vm.assume(address(this).balance >= wrongValue);
        bool wasPlayer;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { wasPlayer = __r; } catch { return; }
        bool reverted;
        try c.wager{value: wrongValue}() { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c.hasPlayerWagered(address(this)) == wasPlayer);
    }

    function testFuzz_run(uint256 wrongValue) public {
        _run(wrongValue);
    }

    receive() external payable {}
}
